/**
 * The hand-written WebP header parser against a standard reader (M6 plan, M6.5): on every
 * file from three encoders, `inspectWebp` must agree with sharp's `metadata()` (libvips and
 * libwebp) on width, height and alpha, and must refuse exactly the files sharp reports as
 * animated or carrying EXIF or XMP.
 *
 * The corpus is generated by scripts/make-webp-corpus.ts. Set WEBP_TEST_DATA to a local
 * checkout of https://github.com/webmproject/libwebp-test-data to add its files; it is not
 * vendored because that repository has no licence file.
 */
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import sharp, { type Metadata } from "sharp";
import { describe, expect, it } from "vitest";
import { inspectWebp, MAX_VARIANT_BYTES } from "../src/server/upload-validate";

const corpusDir = join(import.meta.dirname, "fixtures", "webp");
const files = (dir: string) =>
  readdirSync(dir)
    .filter((f) => f.endsWith(".webp"))
    .sort()
    .map((f) => ({ name: f, path: join(dir, f) }));

const corpus = files(corpusDir);
const external = process.env.WEBP_TEST_DATA && existsSync(process.env.WEBP_TEST_DATA) ? files(process.env.WEBP_TEST_DATA) : [];

describe("WebP corpus", () => {
  it("has at least 30 files from three encoders, at least 10 from each", () => {
    expect(corpus.length).toBeGreaterThanOrEqual(30);
    for (const encoder of ["sharp", "jsquash", "chromium"]) {
      expect(corpus.filter((f) => f.name.startsWith(`${encoder}-`)).length, encoder).toBeGreaterThanOrEqual(10);
    }
  });
});

/** Chunks RFC 9649 defines; anything else (such as RIFF INFO's IART or ICMT) is foreign. */
const WEBP_CHUNKS = new Set(["VP8 ", "VP8L", "VP8X", "ALPH", "ICCP", "ANIM", "ANMF", "EXIF", "XMP "]);

/** The file re-wrapped without its foreign chunks, so the sizes can still be compared. */
function withoutForeignChunks(file: Uint8Array): Uint8Array {
  const view = new DataView(file.buffer, file.byteOffset, file.byteLength);
  const kept: Uint8Array[] = [];
  for (let at = 12; at + 8 <= file.length;) {
    const size = view.getUint32(at + 4, true);
    const end = at + 8 + size + (size % 2);
    if (WEBP_CHUNKS.has(new TextDecoder().decode(file.subarray(at, at + 4)))) kept.push(file.subarray(at, end));
    at = end;
  }
  const out = new Uint8Array(12 + kept.reduce((n, k) => n + k.length, 0));
  out.set(file.subarray(0, 12));
  new DataView(out.buffer).setUint32(4, out.length - 8, true);
  kept.reduce((at, k) => (out.set(k, at), at + k.length), 12);
  return out;
}

/** Same answer as sharp, or, where sharp can't read the file, a refusal. */
async function agreesWithSharp(path: string) {
  let bytes: Uint8Array = new Uint8Array(readFileSync(path));
  let result = inspectWebp(bytes);
  // Two refusals are policy, not parsing, and appear only in libwebp's test data: files over
  // the per-variant limit (checked by length alone) and foreign chunks (checked here).
  if (!result.ok && result.reason === "too-large") {
    expect(bytes.length).toBeGreaterThan(MAX_VARIANT_BYTES);
    return;
  }
  if (!result.ok && result.reason === "bad-chunk" && !WEBP_CHUNKS.has(result.chunk)) {
    bytes = withoutForeignChunks(bytes);
    result = inspectWebp(bytes);
  }

  let meta: Metadata;
  try {
    meta = await sharp(bytes).metadata();
  } catch {
    // libwebp's test data includes files that are broken on purpose.
    expect(result.ok).toBe(false);
    return;
  }
  expect(meta.format).toBe("webp");

  if ((meta.pages ?? 1) > 1) {
    expect(result).toMatchObject({ ok: false, reason: "animated" });
  } else if (meta.exif || meta.xmp) {
    expect(result).toMatchObject({ ok: false, reason: "metadata" });
  } else {
    expect(result).toEqual({ ok: true, width: meta.width, height: meta.height, hasAlpha: meta.hasAlpha, lossless: expect.any(Boolean) });
  }
}

describe("inspectWebp agrees with sharp on the generated corpus", () => {
  it.each(corpus)("$name", ({ path }) => agreesWithSharp(path));
});

describe.runIf(external.length > 0)("inspectWebp agrees with sharp on libwebp's test data (WEBP_TEST_DATA)", () => {
  it.each(external)("$name", ({ path }) => agreesWithSharp(path));
});
